CREATE OR REPLACE FUNCTION public.thepath_packed(p_world uuid, dd deed)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  select dd.world_id is not null and exists (
    select 1 from land_tile t, generate_series(greatest(0, dd.x - dd.radius), dd.x + dd.radius) x
